def _forbidden_control_scope_introducer(
    text: str, opening: int, *, forbid_for: bool = False
) -> str | None:
    parent_stack = _active_brace_stack(text, opening)
    start = _statement_start_at_scope(text, opening, parent_stack)
    introducer = _compact_cpp_code(text[start:opening])
    if re.search(
        r"(?:^|[=(:,?])\[[^\]]*\]"
        r"(?:\([^{}]*\))?(?:mutable)?(?:noexcept(?:\([^{}]*\))?)?"
        r"(?:->[A-Za-z_][^{}]*)?$",
        introducer,
    ):
        return "lambda"
    keywords = (
        "if(",
        "ifconstexpr(",
        "switch(",
        "while(",
        "catch(",
        "else",
        "do",
    ) + (("for(",) if forbid_for else ())
    for keyword in keywords:
        if introducer.startswith(keyword):
            return keyword.rstrip("(")
    return None


def find_function_body(
    text: str, function_name: str
) -> tuple[str | None, int, list[tuple[int, str]]]:
    errors: list[tuple[int, str]] = []
    uses = find_code_identifier_uses(text, function_name)
    if len(uses) != 1:
        errors.append(
            (
                1,
                f"expected exactly one {function_name} definition, found {len(uses)} identifiers",
            )
        )
        return None, 0, errors

    use = uses[0]
    opening = _skip_call_trivia(text, use.offset + len(function_name))
    if opening >= len(text) or text[opening] != "(":
        errors.append(
            (use.line, f"{function_name} is not followed by a parameter list")
        )
        return None, 0, errors
    closing = _matching_parenthesis(text, opening)
    if closing is None:
        errors.append((use.line, f"{function_name} has an unterminated parameter list"))
        return None, 0, errors

    cursor = closing + 1
    body_opening: int | None = None
    while cursor < len(text):
        skipped = _skip_non_code(text, cursor)
        if skipped is not None:
            cursor = skipped
            continue
        if text[cursor].isspace():
            cursor += 1
            continue
        if text[cursor] == ";":
            errors.append((use.line, f"{function_name} is only declared, not defined"))
            return None, 0, errors
        if text[cursor] == "{":
            body_opening = cursor
            break
        cursor += 1
    if body_opening is None:
        errors.append((use.line, f"{function_name} has no function body"))
        return None, 0, errors

    body_closing = _matching_brace(text, body_opening)
    if body_closing is None:
        errors.append((use.line, f"{function_name} has an unterminated function body"))
        return None, 0, errors
    body_line_offset = text.count("\n", 0, body_opening + 1)
    return text[body_opening + 1 : body_closing], body_line_offset, errors


def _function_definition_body_from_uses(
    text: str,
    function_name: str,
    uses: Iterable[CodeIdentifierUse],
) -> tuple[str | None, int, list[tuple[int, str]]]:
    candidates: list[tuple[CodeIdentifierUse, int]] = []
    for use in uses:
        opening = _skip_call_trivia(text, use.offset + len(function_name))
        if opening >= len(text) or text[opening] != "(":
            continue
        closing = _matching_parenthesis(text, opening)
        if closing is None:
            continue
        cursor = _skip_call_trivia(text, closing + 1)
        while True:
            matched_qualifier = False
            for qualifier in ("const", "volatile"):
                if not text.startswith(qualifier, cursor):
                    continue
                after = cursor + len(qualifier)
                boundary = text[after] if after < len(text) else ""
                if boundary.isalnum() or boundary == "_":
                    continue
                cursor = _skip_call_trivia(text, after)
                matched_qualifier = True
                break
            if matched_qualifier:
                continue
            if text.startswith("&&", cursor):
                cursor = _skip_call_trivia(text, cursor + 2)
                continue
            if cursor < len(text) and text[cursor] == "&":
                cursor = _skip_call_trivia(text, cursor + 1)
                continue
            break
        if text.startswith("noexcept", cursor):
            after = cursor + len("noexcept")
            boundary = text[after] if after < len(text) else ""
            if not (boundary.isalnum() or boundary == "_"):
                cursor = _skip_call_trivia(text, after)
                if cursor < len(text) and text[cursor] == "(":
                    noexcept_closing = _matching_parenthesis(text, cursor)
                    if noexcept_closing is None:
                        continue
                    cursor = _skip_call_trivia(text, noexcept_closing + 1)
        while True:
            matched_specifier = False
            for specifier in ("override", "final"):
                if not text.startswith(specifier, cursor):
                    continue
                after = cursor + len(specifier)
                boundary = text[after] if after < len(text) else ""
                if boundary.isalnum() or boundary == "_":
                    continue
                cursor = _skip_call_trivia(text, after)
                matched_specifier = True
                break
            if not matched_specifier:
                break
        if cursor < len(text) and text[cursor] == "{":
            candidates.append((use, cursor))

    if len(candidates) != 1:
        return (
            None,
            0,
            [
                (
                    1,
                    f"expected exactly one {function_name} definition, "
                    f"found {len(candidates)} definitions",
                )
            ],
        )

    use, body_opening = candidates[0]
    body_closing = _matching_brace(text, body_opening)
    if body_closing is None:
        return (
            None,
            0,
            [(use.line, f"{function_name} has an unterminated function body")],
        )
    body_line_offset = text.count("\n", 0, body_opening + 1)
    return text[body_opening + 1 : body_closing], body_line_offset, []


def find_function_definition_body(
    text: str, function_name: str
) -> tuple[str | None, int, list[tuple[int, str]]]:
    """Find one definition while ignoring ordinary calls of the same identifier."""

    return _function_definition_body_from_uses(
        text,
        function_name,
        find_code_identifier_uses(text, function_name),
    )


def find_function_definition_bodies(
    text: str, function_names: Iterable[str]
) -> dict[str, tuple[str | None, int, list[tuple[int, str]]]]:
    """Find many definitions after one comment/literal-safe identifier scan."""

    requested = tuple(dict.fromkeys(function_names))
    if not requested:
        return {}
    masked = _mask_cpp_comments_and_literals(text)
    pattern = re.compile(
        r"\b(?:" + "|".join(re.escape(name) for name in requested) + r")\b"
    )
    newline_offsets = [match.start() for match in re.finditer("\n", text)]
    uses_by_name: dict[str, list[CodeIdentifierUse]] = {
        name: [] for name in requested
    }
    for match in pattern.finditer(masked):
        uses_by_name[match.group(0)].append(
            CodeIdentifierUse(
                line=bisect_right(newline_offsets, match.start() - 1) + 1,
                offset=match.start(),
            )
        )
    return {
        name: _function_definition_body_from_uses(text, name, uses_by_name[name])
        for name in requested
    }


def find_getenv_calls(text: str) -> tuple[list[GetenvCall], list[tuple[int, str]]]:
    calls: list[GetenvCall] = []
    errors: list[tuple[int, str]] = []
    cursor = 0
    while cursor < len(text):
        skipped = _skip_non_code(text, cursor)
        if skipped is not None:
            cursor = skipped
            continue
        if text.startswith("getenv", cursor):
            before = text[cursor - 1] if cursor > 0 else ""
            after_index = cursor + len("getenv")
            after = text[after_index] if after_index < len(text) else ""
            if (before.isalnum() or before == "_") or (after.isalnum() or after == "_"):
                cursor += 1
                continue
            opening = _skip_call_trivia(text, after_index)
            if opening >= len(text) or text[opening] != "(":
                cursor += len("getenv")
                continue
            line = text.count("\n", 0, cursor) + 1
            closing = _matching_parenthesis(text, opening)
            if closing is None:
                errors.append((line, "unterminated getenv call"))
                break
            calls.append(GetenvCall(line=line, argument=text[opening + 1 : closing]))
            cursor = closing + 1
            continue
        cursor += 1
    return calls, errors


def normalize_dynamic_argument(argument: str) -> str:
    return re.sub(r"\s+", "", argument)


def build_flag_categories() -> tuple[dict[str, str], list[str]]:
    result: dict[str, str] = {}
    errors: list[str] = []
    for category, flags in CATEGORY_FLAGS.items():
        for flag in flags:
            previous = result.get(flag)
            if previous is not None:
                errors.append(f"{flag} is classified as both {previous} and {category}")
            result[flag] = category
    return result, errors


_WORKER_CLEANUP_PREPARE_CACHE: dict[str, dict[str, object]] = {}


def _worker_cleanup_prepare_file_signature(
    root: Path, files: set[str]
) -> tuple[tuple[str, int, int], ...] | None:
    signature: list[tuple[str, int, int]] = []
    try:
        for relative in sorted(files):
            stat = (root / relative).stat()
            signature.append((relative, stat.st_size, stat.st_mtime_ns))
    except OSError:
        return None
    return tuple(signature)


class Checks:
    def __init__(self, root: Path) -> None:
        self.root = root
        self.errors: list[str] = []
        self.reads: list[ClassifiedRead] = []
        self.legacy_counts = {entry: 0 for entry in LEGACY_TEST_ONLY_READS}
        self.legacy_execution_policy_literal_counts = {
            entry: 0 for entry in LEGACY_EXECUTION_POLICY_LITERAL_READS
        }
        self.adapter_counts = {
            flag: 0 for flag in EXECUTION_POLICY_ENVIRONMENT_DESCRIPTOR_FLAGS
        }
        self.adapter_seen = False
        self.random_device_counts = {
            relative: 0 for relative in LEGACY_RANDOM_DEVICE_USES
        }
        self.worker_process_call_counts = {
            key: 0 for key in WORKER_PROCESS_REQUIRED_DIRECT_CALLS
        }
        self.merge_prepared_protected_tokens: set[str] = set()
        self.worker_cleanup_macro_closure_prepared = False
        self.worker_cleanup_tier_b_scopes: dict[
            str, list[tuple[str, frozenset[str]]]
        ] = {}
        self.worker_cleanup_macro_closure_files: set[str] = set()
        self.worker_cleanup_include_searches: dict[
            str, set[tuple[str, ...]]
        ] = {}
        self.worker_cleanup_repo_inventory: GitIndexedTextInventory | None = None
        self.wave_result_validated_sources: set[tuple[str, str]] = set()

    def fail(self, relative: str, line: int, message: str) -> None:
        self.errors.append(f"{relative}:{line}: {message}")

    def source_files(self) -> list[tuple[str, Path]]:
        files: list[tuple[str, Path]] = []
        for relative_root in SOURCE_ROOTS:
            directory = self.root / relative_root
            if not directory.is_dir():
                self.fail(relative_root, 1, "source inventory directory is missing")
                continue
            for path in directory.rglob("*"):
                if path.is_file() and path.suffix in SOURCE_SUFFIXES:
                    relative = path.relative_to(self.root).as_posix()
                    files.append((relative, path))
        return sorted(files)

    def bound_work_source_files(self) -> list[tuple[str, Path]]:
        files: list[tuple[str, Path]] = []
        for path in self.root.rglob("*"):
            if not path.is_file() or path.suffix not in SOURCE_SUFFIXES:
                continue
            relative_path = path.relative_to(self.root)
            if not relative_path.parts:
                continue
            top_level = relative_path.parts[0]
            if any(
                top_level.startswith(prefix)
                for prefix in BOUND_WORK_SCAN_EXCLUDED_TOP_LEVEL_PREFIXES
            ):
                continue
            files.append((relative_path.as_posix(), path))
        return sorted(files)

    def prepare_worker_cleanup_receipt_macro_closure(self) -> None:
        if self.worker_cleanup_macro_closure_prepared:
            return
        self.worker_cleanup_macro_closure_prepared = True
        prepare_error_start = len(self.errors)
        root_key = self.root.resolve().as_posix()
        repo_inventory = _git_indexed_text_inventory(self.root)
        self.worker_cleanup_repo_inventory = repo_inventory
        cached = _WORKER_CLEANUP_PREPARE_CACHE.get(root_key)
        if cached is not None:
            tracked_files = set(cached["tracked_files"])
            if (
                repo_inventory == cached["repo_inventory"]
                and _worker_cleanup_prepare_file_signature(
                    self.root, tracked_files
                )
                == cached["signature"]
            ):
                self.worker_cleanup_tier_b_scopes = {
                    relative: list(scopes)
                    for relative, scopes in cached["tier_b_scopes"].items()
                }
                self.worker_cleanup_macro_closure_files = set(
                    cached["closure_files"]
                )
                self.worker_cleanup_include_searches = {
                    relative: set(searches)
                    for relative, searches in cached["include_searches"].items()
                }
                self.errors.extend(cached["errors"])
                return
        for relative, error in repo_inventory.errors:
            self.fail(relative, 1, f"cannot close Git-indexed receipt scan: {error}")
        if (
            WORKER_CLEANUP_RECEIPT_CONTROL_PLANE_POLICY_FILE
            not in repo_inventory.regular_files
            or WORKER_CLEANUP_RECEIPT_CONTROL_PLANE_POLICY_FILE
            not in repo_inventory.text_regular_files
        ):
            self.fail(
                WORKER_CLEANUP_RECEIPT_CONTROL_PLANE_POLICY_FILE,
                1,
                "the sole C++-semantic scan exception must remain a Git-indexed "
                "text regular control-plane file",
            )
        for relative, error in _worker_cleanup_receipt_repo_build_inventory_errors(
            repo_inventory
        ):
            self.fail(relative, 1, error)
        try:
            preset_bytes = (
                self.root / WORKER_CLEANUP_RECEIPT_CMAKE_PRESETS_FILE
            ).read_bytes()
        except OSError as exc:
            self.fail(
                WORKER_CLEANUP_RECEIPT_CMAKE_PRESETS_FILE,
                1,
                f"cannot read committed CMake preset provenance: {exc}",
            )
        else:
            self.validate_worker_cleanup_committed_cmake_presets_surface(
                preset_bytes
            )
        unit_tokens, token_errors = _worker_cleanup_receipt_protected_unit_tokens(
            self.root
        )
        for relative, line, error in token_errors:
            self.fail(relative, line, error)

        try:
            cmake_text = (
                self.root / WORKER_CLEANUP_RECEIPT_CMAKE_FILE
            ).read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            self.fail(
                WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                1,
                f"cannot read committed CMake macro provenance: {exc}",
            )
            cmake_text = ""

        cmake_commands: list[CMakeCommandRecord] = []
        if cmake_text:
            cmake_commands = _cmake_command_records(
                _mask_definitely_inactive_cmake(cmake_text)
            )
            self.validate_worker_cleanup_committed_cmake_surface(
                cmake_text, cmake_commands
            )

        cmake_failures: set[tuple[int, str]] = set()
        for unit, targets in WORKER_CLEANUP_RECEIPT_PROTECTED_UNIT_TARGETS.items():
            tokens = frozenset(
                unit_tokens.get(unit, set())
                | WORKER_CLEANUP_RECEIPT_TIER_A_MACRO_TARGETS
            )
            include_searches, include_search_errors = (
                _cmake_worker_cleanup_include_searches(
                    self.root, cmake_text, set(targets), cmake_commands
                )
            )
            for line, error in include_search_errors:
                cmake_failures.add((line, error))
            if not include_searches:
                include_searches = [("include",)]

            closure: set[str] = set()
            include_failures: set[tuple[str, int, str]] = set()
            for include_search in include_searches:
                search_closure, include_errors = _repo_local_include_closure(
                    self.root, unit, include_search, repo_inventory
                )
                closure.update(search_closure)
                include_failures.update(include_errors)
                for relative in search_closure:
                    self.worker_cleanup_include_searches.setdefault(
                        relative, set()
                    ).add(include_search)
            for relative, line, error in sorted(include_failures):
                self.fail(relative, line, error)

            macros, forced_headers, provenance_errors = (
                _cmake_worker_cleanup_unit_provenance(
                    self.root,
                    cmake_text,
                    set(targets),
                    {unit},
                    cmake_commands,
                )
            )
            for line, error in provenance_errors:
                cmake_failures.add((line, error))
            for macro_name, line, command in macros:
                if macro_name in tokens:
                    cmake_failures.add(
                        (
                            line,
                            "committed CMake macro provenance targets protected "
                            f"token {macro_name} for {unit} via {command}",
                        )
                    )

            for forced_header in forced_headers:
                for include_search in include_searches:
                    forced_closure, forced_errors = _repo_local_include_closure(
                        self.root,
                        forced_header,
                        include_search,
                        repo_inventory,
                    )
                    closure.update(forced_closure)
                    for relative in forced_closure:
                        self.worker_cleanup_include_searches.setdefault(
                            relative, set()
                        ).add(include_search)
                    for relative, line, error in forced_errors:
                        include_failures.add((relative, line, error))

            for relative, line, error in sorted(include_failures):
                rendered = f"{relative}:{line}: {error}"
                if rendered not in self.errors:
                    self.fail(relative, line, error)

            for relative in closure:
                self.worker_cleanup_tier_b_scopes.setdefault(relative, []).append(
                    (unit, tokens)
                )
            self.worker_cleanup_macro_closure_files.update(closure)

        control_plane_closure_error = (
            _worker_cleanup_receipt_control_plane_closure_error(
                self.worker_cleanup_macro_closure_files
            )
        )
        if control_plane_closure_error is not None:
            self.fail(
                WORKER_CLEANUP_RECEIPT_CONTROL_PLANE_POLICY_FILE,
                1,
                control_plane_closure_error,
            )
        for line, error in sorted(cmake_failures):
            self.fail(WORKER_CLEANUP_RECEIPT_CMAKE_FILE, line, error)

        tracked_files = set(repo_inventory.regular_files)
        signature = _worker_cleanup_prepare_file_signature(self.root, tracked_files)
        if signature is not None:
            _WORKER_CLEANUP_PREPARE_CACHE[root_key] = {
                "tracked_files": frozenset(tracked_files),
                "signature": signature,
                "repo_inventory": repo_inventory,
                "tier_b_scopes": {
                    relative: tuple(scopes)
                    for relative, scopes in self.worker_cleanup_tier_b_scopes.items()
                },
                "closure_files": frozenset(
                    self.worker_cleanup_macro_closure_files
                ),
                "include_searches": {
                    relative: frozenset(searches)
                    for relative, searches in self.worker_cleanup_include_searches.items()
                },
                "errors": tuple(self.errors[prepare_error_start:]),
            }

    def validate_worker_cleanup_committed_cmake_presets_surface(
        self, preset_bytes: bytes
    ) -> None:
        if (
            hashlib.sha256(preset_bytes).hexdigest()
            != WORKER_CLEANUP_RECEIPT_CMAKE_PRESETS_SHA256
        ):
            self.fail(
                WORKER_CLEANUP_RECEIPT_CMAKE_PRESETS_FILE,
                1,
                "committed CMake preset semantic surface is not exact",
            )

    def validate_worker_cleanup_receipt_git_indexed_text_inventory(self) -> None:
        """Scan indexed text as C++, except this policy's exact control-plane file.

        The exception remains in the Git inventory, build-file inventory, and
        prepare-cache signature; it is not a protected C++ translation unit or
        a file reachable from the frozen CMake include closure.
        """

        self.prepare_worker_cleanup_receipt_macro_closure()
        repo_inventory = self.worker_cleanup_repo_inventory
        assert repo_inventory is not None
        for relative in repo_inventory.text_regular_files:
            if (
                relative == WORKER_CLEANUP_RECEIPT_CONTROL_PLANE_POLICY_FILE
                and relative not in self.worker_cleanup_macro_closure_files
            ):
                continue
            path = self.root / relative
            try:
                text = path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as exc:
                self.fail(
                    relative,
                    1,
                    f"cannot read Git-indexed receipt scan file: {exc}",
                )
                continue
            self.validate_worker_cleanup_receipt_authority_use_site(relative, text)

    def validate_worker_cleanup_committed_cmake_surface(
        self,
        cmake_text: str,
        commands: list[CMakeCommandRecord] | None = None,
    ) -> None:
        """Keep protected target/source construction literal and command-closed."""

        if (
            hashlib.sha256(
                _mask_cmake_comments(cmake_text).encode("utf-8")
            ).hexdigest()
            != WORKER_CLEANUP_RECEIPT_CMAKE_COMMENT_MASKED_SHA256
        ):
            self.fail(
                WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                1,
                "entire layout-preserving comment-masked CMake surface is not exact",
            )
        if commands is None:
            active = _mask_definitely_inactive_cmake(cmake_text)
            commands = _cmake_command_records(active)
        protected_targets = {
            target
            for targets in WORKER_CLEANUP_RECEIPT_PROTECTED_UNIT_TARGETS.values()
            for target in targets
        }
        protected_sources = set(WORKER_CLEANUP_RECEIPT_PROTECTED_UNIT_TARGETS)
        inert_commands = {
            "message",
            "if",
            "elseif",
            "add_dependencies",
            "add_test",
            "set_tests_properties",
            "install",
        }
        approved_commands = {
            "add_executable",
            "add_library",
            "target_sources",
            "target_include_directories",
            "target_link_libraries",
            "target_compile_definitions",
            "target_compile_options",
            "target_precompile_headers",
            "set_property",
            "set_target_properties",
            "set_source_files_properties",
        }
        target_first_commands = {
            "target_sources",
            "target_include_directories",
            "target_link_libraries",
            "target_compile_definitions",
            "target_compile_options",
            "target_precompile_headers",
        }
        recognized_properties = {
            "COMPILE_DEFINITIONS",
            "COMPILE_OPTIONS",
            "COMPILE_FLAGS",
            "PRECOMPILE_HEADERS",
            "UNITY_BUILD",
        }

        for command in commands:
            body = command.body
            target_hits = {target for target in protected_targets if target in body}
            source_hits = {source for source in protected_sources if source in body}
            if not target_hits and not source_hits:
                continue
            if command.name in inert_commands:
                continue
            if command.name not in approved_commands:
                self.fail(
                    WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                    command.line,
                    "protected worker-cleanup target/source appears in "
                    f"unapproved semantic CMake command {command.name}",
                )
                continue

            first = _cmake_first_argument(body)
            first_target_hits = {
                target
                for target in protected_targets
                if first is not None and target in first
            }
            if command.name in {"add_executable", "add_library"} and first_target_hits:
                if first not in protected_targets:
                    self.fail(
                        WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                        command.line,
                        "protected build target must be a literal first argument",
                    )
            if command.name in target_first_commands and first_target_hits:
                if first not in protected_targets:
                    self.fail(
                        WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                        command.line,
                        "protected target must be the literal first argument of "
                        f"{command.name}",
                    )
            if command.name == "target_sources" and source_hits:
                if first != "gnfs_core":
                    self.fail(
                        WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                        command.line,
                        "protected production source must attach literally to gnfs_core",
                    )
            if command.name == "add_executable" and source_hits:
                mismatched_sources = {
                    source
                    for source in source_hits
                    if first
                    not in WORKER_CLEANUP_RECEIPT_PROTECTED_UNIT_TARGETS[source]
                }
                if mismatched_sources:
                    self.fail(
                        WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                        command.line,
                        "protected test source must attach literally to its frozen "
                        "exact target: " + ", ".join(sorted(mismatched_sources)),
                    )
            for source in source_hits:
                standalone = re.search(
                    rf"(?<![A-Za-z0-9_/$<>{{}}]){re.escape(source)}"
                    rf"(?![A-Za-z0-9_/$<>{{}}])",
                    body,
                )
                if standalone is None:
                    self.fail(
                        WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                        command.line,
                        "protected source path cannot be built from a variable or "
                        f"generator expression: {source}",
                    )

            if command.name in {
                "set_property",
                "set_target_properties",
                "set_source_files_properties",
            }:
                property_at = re.search(r"\bPROPERT(?:Y|IES)\b", body, re.IGNORECASE)
                subject_body = (
                    body if property_at is None else body[: property_at.start()]
                )
                subject_target_hits = {
                    target for target in protected_targets if target in subject_body
                }
                subject_source_hits = {
                    source for source in protected_sources if source in subject_body
                }
                if not subject_target_hits and not subject_source_hits:
                    continue
                properties = {
                    name
                    for name in recognized_properties
                    if re.search(rf"\b{re.escape(name)}\b", body, re.IGNORECASE)
                }
                if not properties:
                    self.fail(
                        WORKER_CLEANUP_RECEIPT_CMAKE_FILE,
                        command.line,
                        "protected target/source forbids unrecognized CMake property mutation",
                    )

    def validate_getenv_identifier_uses(
        self, relative: str, text: str, calls: list[GetenvCall]
    ) -> None:
        getenv_uses = find_code_identifier_uses(text, "getenv")
        non_call_getenv_uses = find_non_call_identifier_uses(text, "getenv")
        for use in non_call_getenv_uses:
            self.fail(
                relative,
                use.line,
                "getenv identifier must be used only as a direct call; "
                "aliases and function-pointer references are forbidden",
            )
        direct_getenv_use_count = len(getenv_uses) - len(non_call_getenv_uses)
        if direct_getenv_use_count != len(calls):
            self.fail(
                relative,
                1,
                f"getenv identifier/direct-call parser mismatch: "
                f"{direct_getenv_use_count} direct identifiers, {len(calls)} parsed calls",
            )

    def validate_durable_ambient_api_uses(self, relative: str, text: str) -> None:
        if relative not in DURABLE_ENVIRONMENT_FREE_FILES:
            return

        for identifier in DURABLE_FORBIDDEN_IDENTIFIERS:
            for use in find_code_identifier_uses(text, identifier):
                self.fail(
                    relative,
                    use.line,
                    f"durable implementation must not use ambient API {identifier}",
                )
        for identifier in DURABLE_FORBIDDEN_CALLS:
            for use in find_call_identifier_uses(text, identifier):
                self.fail(
                    relative,
                    use.line,
                    f"durable implementation must not call ambient API {identifier}",
                )

        if relative in DURABLE_BOUND_WORK_FILES:
            for identifier in DURABLE_BOUND_WORK_FORBIDDEN_IDENTIFIERS:
                for use in find_code_identifier_uses(text, identifier):
                    self.fail(
                        relative,
                        use.line,
                        f"bound-work mapper must not use runtime/side-effect API {identifier}",
                    )

        if relative in MERGE_STREAM_WRITER_FILES:
            for identifier in MERGE_STREAM_WRITER_FORBIDDEN_IDENTIFIERS:
                for use in find_code_identifier_uses(text, identifier):
                    self.fail(
                        relative,
                        use.line,
                        f"streaming merge writer must not use authority/full-corpus API "
                        f"{identifier}",
                    )

        if relative not in DURABLE_PURE_RUNTIME_MAPPER_FILES:
            return
        for identifier in DURABLE_PURE_RUNTIME_MAPPER_FORBIDDEN_IDENTIFIERS:
            for use in find_code_identifier_uses(text, identifier):
                self.fail(
                    relative,
                    use.line,
                    f"pure runtime mapper must not use legacy runtime API {identifier}",
                )
        for identifier in DURABLE_PURE_RUNTIME_MAPPER_FORBIDDEN_CALLS:
            for use in find_call_identifier_uses(text, identifier):
                self.fail(
                    relative,
                    use.line,
                    f"pure runtime mapper must not call legacy runtime API {identifier}",
                )

    def validate_worker_process_transport_boundary(
        self, relative: str, text: str
    ) -> None:
        if not relative.startswith(WORKER_PROCESS_POLICY_PREFIXES):
            return

        for identifier, allowed_files in WORKER_PROCESS_DIRECT_CALL_ALLOWLIST.items():
            uses = find_code_identifier_uses(text, identifier)
            calls = find_call_identifier_uses(text, identifier)
            if relative not in allowed_files:
                for use in uses:
                    self.fail(
                        relative,
                        use.line,
                        f"production {identifier} authority belongs only to "
                        f"{', '.join(sorted(allowed_files))}",
                    )
                continue
            count_key = (relative, identifier)
            if count_key in self.worker_process_call_counts:
                self.worker_process_call_counts[count_key] += len(calls)
            if len(uses) != len(calls):
                non_call_offsets = {
                    use.offset
                    for use in find_non_call_identifier_uses(text, identifier)
                }
                for use in uses:
                    if use.offset in non_call_offsets:
                        self.fail(
                            relative,
                            use.line,
                            f"{identifier} authority must be used only as a direct call",
                        )

        for identifier, use in find_code_identifier_tokens(text):
            if identifier in WORKER_PROCESS_FORBIDDEN_PROCESS_IDENTIFIERS:
                self.fail(
                    relative,
                    use.line,
                    f"sieve process policy forbids alternate API {identifier}",
                )

        if relative not in WORKER_PROCESS_TRANSPORT_FILES:
            return
        for identifier in WORKER_PROCESS_TRANSPORT_FORBIDDEN_IDENTIFIERS:
            for use in find_code_identifier_uses(text, identifier):
                self.fail(
                    relative,
                    use.line,
                    f"self-exec process transport must not use {identifier}",
                )

    def validate_legacy_pipeline_boundary(self, text: str) -> None:
        for identifier in LEGACY_PIPELINE_DURABLE_FORBIDDEN_IDENTIFIERS:
            for use in find_code_identifier_uses(text, identifier):
                self.fail(
                    LEGACY_PIPELINE_FILE,
                    use.line,
                    f"legacy Pipeline must not self-mint durable work via {identifier}",
                )

    def validate_bound_work_use_site(self, relative: str, text: str) -> None:
        bound_uses: list[CodeIdentifierUse] = []
        for identifier in BOUND_WORK_USE_SITE_IDENTIFIERS:
            uses = find_code_identifier_uses(text, identifier)
            bound_uses.extend(uses)
            if relative not in BOUND_WORK_USE_SITE_ALLOWLIST:
                for use in uses:
                    self.fail(
                        relative,
                        use.line,
                        f"bound-work use site is not receipt-gated/allowlisted: {identifier}",
                    )
        if bound_uses:
            for use in find_code_identifier_uses(text, "run_distributed_sieve"):
                self.fail(
                    relative,
                    use.line,
                    "bound-work projection must not coexist with the legacy seeded runner",
                )

